SourceCode.Declaration:
/// <summary>
/// Data event handler on <c>CustTable</c> to detect customer creation and relevant updates
/// and enqueue eligible B2C customers into <c>UTCSFCustomerPushQueue</c>.
/// Uses <c>DataEventHandler</c> instead of CoC so it remains resilient to optional parameter
/// changes on <c>CustTable.insert()</c> and <c>CustTable.update()</c> across D365 F&amp;O versions.
/// </summary>
public static class UTCSFCustTable_Extension
{
}

Method.Source:
[DataEventHandler(tableStr(CustTable), DataEventType::Inserted)]
public static void CustTable_onInserted(Common _sender, DataEventArgs _e)
{
    CustTable custTable = _sender as CustTable;

    if (custTable)
    {
        UTCSFCustomerChangeHandler::tryEnqueueCustTable(custTable);
    }
}

[DataEventHandler(tableStr(CustTable), DataEventType::Updating)]
public static void CustTable_onUpdating(Common _sender, DataEventArgs _e)
{
    CustTable custTable = _sender as CustTable;

    if (!custTable)
    {
        return;
    }

    CustTable origCustTable = custTable.orig();

    boolean hasRelevantChange = (custTable.CustGroup  != origCustTable.CustGroup
                              || custTable.Blocked    != origCustTable.Blocked
                              || custTable.Party      != origCustTable.Party
                              || custTable.AccountNum != origCustTable.AccountNum);

    if (hasRelevantChange)
    {
        UTCSFCustomerChangeHandler::tryEnqueueCustTable(custTable);
    }
}
